#!/bin/sh
# Idempotently creates one database and one least-privilege login role per
# service (database-per-service). Runs as the one-shot "postgres-init"
# compose service on every `docker compose up`, so it also upgrades volumes
# created before the services existed. Passwords come from the environment
# (.env generated by `make dev-env`) and are passed to psql as variables,
# never interpolated into SQL text by the shell.
set -eu

create() {
  db="$1"; role="$2"; pass="$3"
  psql -v ON_ERROR_STOP=1 -v db="$db" -v role="$role" -v pass="$pass" <<'SQL'
SELECT format('CREATE ROLE %I LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION CONNECTION LIMIT 40', :'role')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'role') \gexec
SELECT format('ALTER ROLE %I PASSWORD %L', :'role', :'pass') \gexec
SELECT format('CREATE DATABASE %I OWNER %I', :'db', :'role')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'db') \gexec
SELECT format('REVOKE ALL ON DATABASE %I FROM PUBLIC', :'db') \gexec
SELECT format('GRANT CONNECT, TEMPORARY ON DATABASE %I TO %I', :'db', :'role') \gexec
SQL
  # Only the owning service role may create objects in its database.
  psql -v ON_ERROR_STOP=1 -d "$db" -v role="$role" <<'SQL'
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
SELECT format('ALTER SCHEMA public OWNER TO %I', :'role') \gexec
SQL
}

create auth auth_svc "$AUTH_DB_PASSWORD"
create quizzes quizzes_svc "$QUIZZES_DB_PASSWORD"
echo "service databases ready"
